import {
  Modal as ChakraModal,
  ModalOverlay,
  ModalContent,
  Box,
  ModalContentProps,
} from '@chakra-ui/react'

import { IModal } from '../types'
import { ModalContentBase } from './ModalContentBase'
import { useModalConfig } from './useModalConfig'

const StyledModalContent = ModalContent as React.FC<ModalContentProps>

export const uiKitModalIsDesktop = 641
export const ModalPadding = {
  py: '32px',
  px: '24px',
}

export const Modal = ({
  children,
  closeOnOverlayClick = true,
  fixedSubtitle,
  isOpen,
  onClose,
  title,
  withoutMargin = false,
  scrollBehavior = 'outside',
  fixedButtons = false,
  autoFocus = false,
  returnFocusOnClose = true,
  minWidth,
  maxWidth,
  minHeight,
  maxHeight,
}: IModal): JSX.Element => {
  const isInside = scrollBehavior === 'inside' || fixedButtons

  const modalConfig = useModalConfig({
    closeOnOverlayClick,
    scrollBehavior,
    fixedButtons,
    withoutMargin,
    minWidth,
    maxWidth,
    minHeight,
    maxHeight,
  })

  return (
    <ChakraModal
      closeOnOverlayClick={modalConfig.closeOnOverlayClick}
      closeOnEsc={modalConfig.closeOnEsc}
      isOpen={isOpen}
      motionPreset="scale"
      onClose={onClose}
      scrollBehavior={isInside ? 'inside' : 'outside'}
      autoFocus={autoFocus}
      returnFocusOnClose={returnFocusOnClose}
      blockScrollOnMount={false}
    >
      <ModalOverlay />
      <Box
        sx={{
          ...(isInside && {
            '.uikit-modalContent': {
              pb: '16px !important',
            },
            '.uikit-modalButtons': {
              boxShadow: '0px 4px 16px 0px #5C5C5C33',
            },
          }),
        }}
      >
        <StyledModalContent {...modalConfig.contentProps}>
          <ModalContentBase
            fixedButtons={fixedButtons}
            withoutMargin={withoutMargin}
            title={title}
            closeOnOverlayClick={closeOnOverlayClick}
            fixedSubtitle={fixedSubtitle}
          >
            {children}
          </ModalContentBase>
        </StyledModalContent>
      </Box>
    </ChakraModal>
  )
}
